using System;
using System.Collections.Generic;
using UnityEngine;

namespace IslandMap
{
    /// <summary>
    /// A planned location on the island, annotated by the project owner (NOT generated by the map tools).
    /// Stored as JSON (Docs/IslandMap/markers.json) so it can be edited outside Unity. All coordinates are Unity
    /// world space in metres (+X east, +Z north, +Y up).
    /// </summary>
    [Serializable]
    public class MapMarker
    {
        public string Id = "";
        public string Name = "";
        [Tooltip("Anchor point in world space. Y may be 0 if unknown; tools fill it from the terrain.")]
        public Vector3 Position;
        [Tooltip("Construction zone outline as world X/Z points (clockwise or counter-clockwise). Empty = point only.")]
        public List<Vector2> Zone = new List<Vector2>();
        public List<string> AssetRequirements = new List<string>();
        public string Purpose = "";
        [Tooltip("Git branch the construction work is assigned to.")]
        public string AssignedBranch = "";
        [Tooltip("One of MapMarker.Statuses.")]
        public string Status = "Proposed";
        public string Notes = "";

        public static readonly string[] Statuses = { "Proposed", "Approved", "Assigned", "InProgress", "Built", "OnHold", "Rejected" };
        public bool HasValidStatus => Array.IndexOf(Statuses, Status) >= 0;

        /// <summary>Zone bounds in world X/Z (a 0-size rect at Position when there is no zone).</summary>
        public Rect ZoneBounds
        {
            get
            {
                if (Zone == null || Zone.Count == 0) return new Rect(Position.x, Position.z, 0, 0);
                Vector2 mn = Zone[0], mx = Zone[0];
                foreach (var p in Zone) { mn = Vector2.Min(mn, p); mx = Vector2.Max(mx, p); }
                return Rect.MinMaxRect(mn.x, mn.y, mx.x, mx.y);
            }
        }

        public bool ZoneContains(Vector2 xz)
        {
            if (Zone == null || Zone.Count < 3) return false;
            bool inside = false;
            for (int i = 0, j = Zone.Count - 1; i < Zone.Count; j = i++)
                if ((Zone[i].y > xz.y) != (Zone[j].y > xz.y) &&
                    xz.x < (Zone[j].x - Zone[i].x) * (xz.y - Zone[i].y) / (Zone[j].y - Zone[i].y) + Zone[i].x)
                    inside = !inside;
            return inside;
        }
    }

    [Serializable]
    public class MapMarkerSet
    {
        public int Version = 1;
        public string CoordinateSystem = "Unity world space, metres, +X east, +Z north, +Y up";
        public List<MapMarker> Markers = new List<MapMarker>();

        public string ToJson() => JsonUtility.ToJson(this, true);
        public static MapMarkerSet FromJson(string json) => string.IsNullOrWhiteSpace(json) ? new MapMarkerSet() : JsonUtility.FromJson<MapMarkerSet>(json) ?? new MapMarkerSet();

        /// <summary>Problems a reviewer should fix (duplicate ids, unknown status, positions outside the map).</summary>
        public List<string> Validate(MapProjection projection)
        {
            var issues = new List<string>();
            var ids = new HashSet<string>();
            foreach (var m in Markers)
            {
                string tag = string.IsNullOrEmpty(m.Name) ? m.Id : m.Name;
                if (string.IsNullOrEmpty(m.Id)) issues.Add($"'{tag}': missing Id");
                else if (!ids.Add(m.Id)) issues.Add($"'{tag}': duplicate Id {m.Id}");
                if (!m.HasValidStatus) issues.Add($"'{tag}': unknown Status '{m.Status}' (use {string.Join(", ", MapMarker.Statuses)})");
                if (!projection.ContainsWorld(m.Position)) issues.Add($"'{tag}': position {m.Position} is outside the mapped area");
                if (m.Zone != null) foreach (var p in m.Zone) if (!projection.WorldRect.Contains(p)) { issues.Add($"'{tag}': zone point {p} is outside the mapped area"); break; }
            }
            return issues;
        }
    }
}
